/**
 * Debounces a function so it only executes after a specified delay has passed
 * since the last invocation. Returns a debounced function with a `cancel()`
 * method to clear any pending invocation.
 *
 * @param fn - The function to debounce.
 * @param ms - The delay in milliseconds before the function is executed.
 * @returns A debounced function that accepts the same arguments as `fn`,
 *          with an additional `cancel()` method to cancel any pending call.
 *
 * @example
 * const debouncedSearch = debounce((query: string) => {
 *   console.log(`Searching for: ${query}`);
 * }, 300);
 *
 * debouncedSearch("hello");
 * debouncedSearch("hello world");
 * // After 300ms, only "hello world" is logged.
 *
 * debouncedSearch.cancel();
 * // Cancels any pending invocation.
 */
function debounce<T extends (...args: any[]) => void>(
  fn: T,
  ms: number
): T & { cancel: () => void } {
  let timeoutId: ReturnType<typeof setTimeout> | null = null;

  const debounced: T & { cancel: () => void } = ((...args: Parameters<T>) => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
    timeoutId = setTimeout(() => {
      timeoutId = null;
      fn(...args);
    }, ms);
  }) as T & { cancel: () => void };

  debounced.cancel = () => {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  return debounced;
}
